const input = $json || {};

const sampleLifeImpactOutput = {
  success: true,
  result: {
    topLifeOpportunities: [
      {
        lifeRank: 1,
        id: 'social-1',
        title: 'International Social Mixer',
        category: 'social',
        source: 'InterNations',
        start: '2026-08-01T19:30:00+04:00',
        end: '2026-08-01T22:00:00+04:00',
        location: 'Dubai Marina',
        estimatedCost: 120,
        currency: 'AED',
        finalScore: 92,
        lifeImpactScore: 95,
        personalFitScore: 90,
        eventScore: 88,
        confidenceScore: 90,
        lifeClassification: 'Transformative Opportunity',
        reason: 'Strong dating and social-circle potential.'
      },
      {
        lifeRank: 2,
        id: 'nightlife-1',
        title: 'Rooftop Social Night',
        category: 'nightlife',
        source: 'TimeOut Dubai',
        start: '2026-08-01T22:30:00+04:00',
        end: '2026-08-02T01:00:00+04:00',
        location: 'Palm Jumeirah',
        estimatedCost: 180,
        currency: 'AED',
        finalScore: 87,
        lifeImpactScore: 90,
        personalFitScore: 88,
        eventScore: 82,
        confidenceScore: 82,
        lifeClassification: 'High Life Impact',
        reason: 'Strong nightlife and dating potential.'
      },
      {
        lifeRank: 3,
        id: 'fitness-1',
        title: 'Boxing Class',
        category: 'fitness',
        source: 'Privilee',
        start: '2026-08-02T11:00:00+04:00',
        end: '2026-08-02T12:00:00+04:00',
        location: 'Palm Jumeirah',
        estimatedCost: 0,
        currency: 'AED',
        finalScore: 83,
        lifeImpactScore: 84,
        personalFitScore: 91,
        eventScore: 80,
        confidenceScore: 95,
        lifeClassification: 'High Life Impact',
        reason: 'Supports fitness and confidence.'
      },
      {
        lifeRank: 4,
        id: 'travel-1',
        title: 'Weekend Muscat Escape',
        category: 'travel',
        source: 'Skyscanner',
        start: '2026-08-02T14:00:00+04:00',
        end: '2026-08-03T20:00:00+04:00',
        location: 'Muscat',
        estimatedCost: 850,
        currency: 'AED',
        finalScore: 81,
        lifeImpactScore: 92,
        personalFitScore: 74,
        eventScore: 79,
        confidenceScore: 88,
        lifeClassification: 'High Life Impact',
        reason: 'High travel and novelty value.'
      }
    ]
  }
};

const source =
  input.lifeImpactOutput ||
  (
    input.result?.topLifeOpportunities
      ? input
      : sampleLifeImpactOutput
  );

return [{
  json: {
    request: input.request || {
      text: 'Bu hafta sonunu planla',
      channel: 'manual_test',
      userId: 'savas'
    },
    context: input.context || {
      timezone: 'Asia/Dubai',
      userContext: {
        identity: { name: 'Savaş', language: 'Turkish' }
      },
      calendarContext: {
        thisWeek: []
      },
      derivedContext: {
        calendarLoad: 'low',
        isWeekend: true,
        needsMoreSocial: true,
        needsMoreFitness: true,
        needsFinanceReview: false,
        preferredPlanningWindow: {
          start: '17:00',
          end: '23:00'
        }
      },
      userState: {
        energyLevel: 'high',
        mood: 'social',
        budgetAED: 1200,
        maxTravelMinutes: 45
      }
    },
    opportunities:
      source.result?.topLifeOpportunities ||
      source.topLifeOpportunities ||
      [],
    metadata: input.metadata || {
      correlationId: `life-strategy-${Date.now()}`,
      testMode: true
    }
  }
}];

const input = $json || {};
const opportunities = Array.isArray(input.opportunities)
  ? input.opportunities
  : [];

const context = input.context || {};
const derived =
  context.derivedContext ||
  context.derived ||
  {};
const userState = context.userState || {};
const metadata = input.metadata || {};

const parseDate = value => {
  if (!value) return null;
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? null : date;
};

const overlaps = (aStart, aEnd, bStart, bEnd) => {
  if (!aStart || !aEnd || !bStart || !bEnd) return false;
  return aStart < bEnd && aEnd > bStart;
};

const categoryPriority = {
  dating: 100,
  social: 95,
  nightlife: 90,
  travel: 85,
  fitness: 75,
  wellness: 70,
  style: 65,
  career: 55,
  learning: 50,
  finance: 40,
  general: 45
};

const categoryGroup = category => {
  const value = String(category || 'general').toLowerCase();

  if (value.includes('dating')) return 'dating';
  if (value.includes('social') || value.includes('network')) return 'social';
  if (value.includes('night')) return 'nightlife';
  if (value.includes('travel') || value.includes('trip')) return 'travel';
  if (value.includes('fitness') || value.includes('sport')) return 'fitness';
  if (value.includes('wellness') || value.includes('recovery')) return 'wellness';
  if (value.includes('style') || value.includes('groom')) return 'style';
  if (value.includes('career')) return 'career';
  if (value.includes('learn')) return 'learning';
  if (value.includes('finance')) return 'finance';

  return 'general';
};

const getDayKey = date =>
  date
    ? new Intl.DateTimeFormat('en-CA', {
        timeZone: 'Asia/Dubai',
        year: 'numeric',
        month: '2-digit',
        day: '2-digit'
      }).format(date)
    : 'unscheduled';

const getTimeLabel = date =>
  date
    ? new Intl.DateTimeFormat('en-GB', {
        timeZone: 'Asia/Dubai',
        hour: '2-digit',
        minute: '2-digit',
        hour12: false
      }).format(date)
    : null;

const getWeekday = date =>
  date
    ? new Intl.DateTimeFormat('en-US', {
        timeZone: 'Asia/Dubai',
        weekday: 'long'
      }).format(date)
    : 'Unscheduled';

const budgetAED = Number(userState.budgetAED);
let plannedCost = 0;

const prepared = opportunities.map((item, index) => {
  const start = parseDate(item.start);
  const end = parseDate(item.end);
  const group = categoryGroup(item.category);

  const basePriority =
    Number(item.finalScore ?? item.lifeImpactScore ?? 0) +
    (categoryPriority[group] || 0) * 0.10;

  let strategyAdjustment = 0;
  const strategyReasons = [];

  if (
    derived.needsMoreSocial === true &&
    ['dating', 'social', 'nightlife'].includes(group)
  ) {
    strategyAdjustment += 8;
    strategyReasons.push('Social target is below goal.');
  }

  if (
    derived.needsMoreFitness === true &&
    group === 'fitness'
  ) {
    strategyAdjustment += 6;
    strategyReasons.push('Fitness target is below goal.');
  }

  if (
    derived.calendarLoad === 'high' &&
    !['wellness'].includes(group)
  ) {
    strategyAdjustment -= 10;
    strategyReasons.push('Calendar load is high.');
  }

  if (
    String(userState.mood || '').toLowerCase() === 'social' &&
    ['dating', 'social', 'nightlife'].includes(group)
  ) {
    strategyAdjustment += 5;
    strategyReasons.push('Current mood is social.');
  }

  if (
    String(userState.energyLevel || '').toLowerCase() === 'low' &&
    ['nightlife', 'travel', 'fitness'].includes(group)
  ) {
    strategyAdjustment -= 8;
    strategyReasons.push('Current energy is low.');
  }

  const cost = Number(item.estimatedCost ?? 0);

  if (Number.isFinite(cost) && Number.isFinite(budgetAED)) {
    if (cost <= budgetAED) {
      strategyAdjustment += 2;
      strategyReasons.push('Within stated budget.');
    } else {
      strategyAdjustment -= 12;
      strategyReasons.push('Exceeds stated budget.');
    }
  }

  return {
    ...item,
    startDate: start,
    endDate: end,
    strategyGroup: group,
    strategyScore:
      Math.max(
        0,
        Math.min(
          100,
          Math.round(basePriority + strategyAdjustment)
        )
      ),
    strategyReasons,
    originalIndex: index
  };
});

prepared.sort((a, b) => {
  if (b.strategyScore !== a.strategyScore) {
    return b.strategyScore - a.strategyScore;
  }

  const aStart = a.startDate?.getTime() ?? Number.MAX_SAFE_INTEGER;
  const bStart = b.startDate?.getTime() ?? Number.MAX_SAFE_INTEGER;

  return aStart - bStart;
});

const selected = [];
const rejected = [];
const selectedCategories = new Set();
const selectedPerDay = new Map();

for (const item of prepared) {
  const group = item.strategyGroup;
  const dayKey = getDayKey(item.startDate);
  const sameDayCount = selectedPerDay.get(dayKey) || 0;
  const cost = Number(item.estimatedCost ?? 0);

  if (
    Number.isFinite(budgetAED) &&
    Number.isFinite(cost) &&
    plannedCost + cost > budgetAED
  ) {
    rejected.push({
      id: item.id,
      title: item.title,
      reason: 'budget_limit',
      strategyScore: item.strategyScore
    });
    continue;
  }

  if (sameDayCount >= 3) {
    rejected.push({
      id: item.id,
      title: item.title,
      reason: 'daily_activity_limit',
      strategyScore: item.strategyScore
    });
    continue;
  }

  const conflict = selected.find(existing =>
    overlaps(
      item.startDate,
      item.endDate,
      existing.startDate,
      existing.endDate
    )
  );

  if (conflict) {
    rejected.push({
      id: item.id,
      title: item.title,
      reason: 'time_conflict',
      conflictsWith: conflict.id,
      strategyScore: item.strategyScore
    });
    continue;
  }

  // Avoid too much nightlife without balance.
  const nightlifeCount =
    selected.filter(x => x.strategyGroup === 'nightlife').length;

  if (group === 'nightlife' && nightlifeCount >= 2) {
    rejected.push({
      id: item.id,
      title: item.title,
      reason: 'nightlife_balance_limit',
      strategyScore: item.strategyScore
    });
    continue;
  }

  selected.push(item);
  selectedCategories.add(group);
  selectedPerDay.set(dayKey, sameDayCount + 1);

  if (Number.isFinite(cost)) {
    plannedCost += cost;
  }

  if (selected.length >= 6) break;
}

const hasSocial =
  selected.some(item =>
    ['dating', 'social', 'nightlife'].includes(item.strategyGroup)
  );

const hasFitness =
  selected.some(item => item.strategyGroup === 'fitness');

const hasRecovery =
  selected.some(item => item.strategyGroup === 'wellness');

const strategyWarnings = [];

if (!hasSocial && derived.needsMoreSocial === true) {
  strategyWarnings.push('No social or dating opportunity was selected.');
}

if (!hasFitness && derived.needsMoreFitness === true) {
  strategyWarnings.push('No fitness activity was selected.');
}

if (
  selected.filter(item => item.strategyGroup === 'nightlife').length >= 2 &&
  !hasRecovery
) {
  strategyWarnings.push('Consider adding a recovery block after multiple nightlife activities.');
}

const dailyPlanMap = new Map();

for (const item of selected) {
  const dayKey = getDayKey(item.startDate);

  if (!dailyPlanMap.has(dayKey)) {
    dailyPlanMap.set(dayKey, {
      date: dayKey,
      weekday: getWeekday(item.startDate),
      activities: []
    });
  }

  dailyPlanMap.get(dayKey).activities.push({
    recommendationId: item.id,
    title: item.title,
    category: item.category,
    strategyGroup: item.strategyGroup,
    start: item.start,
    end: item.end,
    startTime: getTimeLabel(item.startDate),
    endTime: getTimeLabel(item.endDate),
    location: item.location || null,
    estimatedCost: item.estimatedCost ?? null,
    currency: item.currency || 'AED',
    finalScore: item.finalScore ?? null,
    lifeImpactScore: item.lifeImpactScore ?? null,
    strategyScore: item.strategyScore,
    classification: item.lifeClassification || null,
    reason: item.reason || '',
    strategyReasons: item.strategyReasons
  });
}

const dailyPlan = [...dailyPlanMap.values()]
  .map(day => ({
    ...day,
    activities: day.activities.sort((a, b) =>
      String(a.start || '').localeCompare(String(b.start || ''))
    )
  }))
  .sort((a, b) => a.date.localeCompare(b.date));

const planType =
  dailyPlan.length > 1
    ? 'multi_day'
    : dailyPlan.length === 1
      ? 'single_day'
      : 'empty';

const focusSummary = {
  datingAndSocialCount:
    selected.filter(item =>
      ['dating', 'social'].includes(item.strategyGroup)
    ).length,
  nightlifeCount:
    selected.filter(item => item.strategyGroup === 'nightlife').length,
  travelCount:
    selected.filter(item => item.strategyGroup === 'travel').length,
  fitnessCount:
    selected.filter(item => item.strategyGroup === 'fitness').length,
  wellnessCount:
    selected.filter(item => item.strategyGroup === 'wellness').length,
  careerLearningCount:
    selected.filter(item =>
      ['career', 'learning'].includes(item.strategyGroup)
    ).length
};

const strategyNarrative = [];

if (focusSummary.datingAndSocialCount > 0) {
  strategyNarrative.push('The plan prioritizes dating and social-circle growth.');
}

if (focusSummary.nightlifeCount > 0) {
  strategyNarrative.push('Nightlife is included without allowing it to dominate the plan.');
}

if (focusSummary.travelCount > 0) {
  strategyNarrative.push('Travel is included when budget and timing permit.');
}

if (focusSummary.fitnessCount > 0) {
  strategyNarrative.push('Fitness is included to protect consistency and confidence.');
}

if (strategyWarnings.length) {
  strategyNarrative.push(...strategyWarnings);
}

const actionInputs = selected.map(item => ({
  id: item.id,
  title: item.title,
  category: item.category,
  source: item.source,
  sourceUrl: item.sourceUrl || null,
  start: item.start || null,
  end: item.end || null,
  location: item.location || null,
  estimatedCost: item.estimatedCost ?? null,
  currency: item.currency || 'AED',
  confidence: Number(item.confidence ?? 0.5),
  reason:
    item.reason ||
    item.strategyReasons.join(' '),
  score:
    item.finalScore ??
    item.strategyScore,
  classification:
    item.lifeClassification ||
    'Strategic Selection',
  strategyScore: item.strategyScore,
  lifeImpactScore: item.lifeImpactScore ?? null,
  requiresApproval: false
}));

return [{
  json: {
    success: true,
    result: {
      planType,
      strategySummary: {
        opportunityCount: opportunities.length,
        selectedCount: selected.length,
        rejectedCount: rejected.length,
        plannedCost,
        budgetAED:
          Number.isFinite(budgetAED)
            ? budgetAED
            : null,
        focusSummary,
        warnings: strategyWarnings
      },
      dailyPlan,
      selectedOpportunities: selected.map(item => ({
        id: item.id,
        title: item.title,
        category: item.category,
        strategyGroup: item.strategyGroup,
        strategyScore: item.strategyScore,
        finalScore: item.finalScore ?? null,
        lifeImpactScore: item.lifeImpactScore ?? null,
        start: item.start || null,
        end: item.end || null,
        location: item.location || null,
        estimatedCost: item.estimatedCost ?? null,
        currency: item.currency || 'AED',
        strategyReasons: item.strategyReasons
      })),
      rejectedOpportunities: rejected,
      strategyNarrative,
      actionPlannerInput: {
        recommendations: actionInputs
      }
    },
    memoryUpdates: selected.map(item => ({
      type: 'life_strategy_selection',
      operation: 'append',
      payload: {
        recommendationId: item.id,
        title: item.title,
        category: item.category,
        strategyScore: item.strategyScore,
        selectedAt: new Date().toISOString()
      }
    })),
    approvalRequests: [],
    logs: [{
      timestamp: new Date().toISOString(),
      workflow: 'Concierge OS - Life Strategy Engine',
      level:
        strategyWarnings.length
          ? 'warning'
          : 'info',
      correlationId: metadata.correlationId || '',
      message:
        `Built a ${planType} strategy with ${selected.length} selected opportunities.`,
      details: {
        selectedCount: selected.length,
        rejectedCount: rejected.length,
        plannedCost,
        focusSummary,
        strategyWarnings
      }
    }],
    nextAction: {
      type: 'build_action_plan',
      targetWorkflow: 'Concierge OS - Action Planner'
    },
    error: null
  }
}];
